# conductor_client.py — a typed client for code-conductor's /mcp server.
#
# Generated by code-conductor from its MCP tool registry at every boot; do not
# edit: the file is overwritten. Needs Python 3.11+ and the standard library
# only. Contract: docs/mcp-applications.md → Client libraries.
import sys

if sys.version_info < (3, 11):
    raise ImportError('conductor_client needs Python 3.11 or newer')

import json
import os
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Literal, NotRequired, TypedDict

DEFAULT_URL = 'http://127.0.0.1:8787/mcp'

# cc listens on loopback: an inherited http_proxy must not route to it.
_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))

# An omitted argument: never sent, unlike None, which is sent as null.
_OMIT: Any = object()


def _args(d: dict[str, Any]) -> dict[str, Any]:
    return {k: v for k, v in d.items() if v is not _OMIT}


class ConductorError(Exception):
    """A refusal or a fault from cc.

    status is the HTTP status: 200 for a tool's own refusal, 4xx/5xx for a
    protocol fault. code is None when the response was not JSON.
    """

    def __init__(self, code: str | None, reason: str, status: int, body: Any):
        super().__init__(f"{code}: {reason} (HTTP {status})")
        self.code = code
        self.reason = reason
        self.status = status
        self.body = body


MakeThingResultOwner = TypedDict("MakeThingResultOwner", {
    "name": str,
})

MakeThingResultPartsItem = TypedDict("MakeThingResultPartsItem", {
    "at": int,
})

MakeThingResultPolicyVariant2 = TypedDict("MakeThingResultPolicyVariant2", {
    "limit": int,
})

MakeThingResult = TypedDict("MakeThingResult", {
    "id": str,
    "note": NotRequired[str],
    "size": int | None,
    "owner": MakeThingResultOwner | None,
    "state": Literal["open", "closed"] | None,
    "ok": Literal[True],
    "parts": list[MakeThingResultPartsItem],
    "scores": dict[str, float],
    # Pass-through metadata.
    "meta": dict[str, Any],
    "pin": str | float | bool | None,
    "policy": Literal["allow", "deny"] | MakeThingResultPolicyVariant2,
    # Anything at all.
    "input": Any,
})

PickOneResultVariant1 = TypedDict("PickOneResultVariant1", {
    "picked": Literal["a"],
    "a": str,
})

PickOneResultVariant2 = TypedDict("PickOneResultVariant2", {
    "picked": Literal["b"],
})

PickOneResult = PickOneResultVariant1 | PickOneResultVariant2


class ConductorClient:
    """One cc /mcp endpoint. Calls are attributed to the session the URL names."""

    def __init__(self, url: str | None = None):
        self.url = (url or os.environ.get('CONDUCTOR_MCP_URL') or DEFAULT_URL).rstrip('/')

    def call(self, name: str, args: dict[str, Any] | None = None) -> Any:
        """Call any tool by name, plugin tools included; returns the parsed JSON body."""
        req = urllib.request.Request(
            f"{self.url}/tools/{urllib.parse.quote(name, safe='')}",
            data=json.dumps({} if args is None else args).encode('utf-8'),
            headers={'content-type': 'application/json'},
            method='POST',
        )
        try:
            with _OPENER.open(req) as res:
                status, text = res.status, res.read().decode('utf-8')
        except urllib.error.HTTPError as e:
            status, text = e.code, e.read().decode('utf-8')
        try:
            body = json.loads(text)
        except ValueError:
            raise ConductorError(None, 'response is not JSON', status, text) from None
        if status >= 400 or (isinstance(body, dict) and body.get('ok') is False):
            obj = body if isinstance(body, dict) else {}
            raise ConductorError(obj.get('code'), obj.get('reason', f'HTTP {status}'), status, body)
        return body

    def make_thing(self, *, name: str, count: int = _OMIT, label: str | None = _OMIT, kind: Literal["small", "large"] = _OMIT, extra: dict[str, Any] = _OMIT, from_: str = _OMIT, tags: list[str] = _OMIT) -> MakeThingResult:
        """Make a thing.
        A second line with a \"\"\" triple quote, a */ comment end and a \\ backslash.

        Args:
            name: The thing's name.
            count: How many. (default: 3)
            label: A label, or null to clear it.
            kind: Which kind.
            extra: Free-form {key: value} pairs.
            from_: Where it comes from.
            tags:
        """
        return self.call('make_thing', _args({'name': name, 'count': count, 'label': label, 'kind': kind, 'extra': extra, 'from': from_, 'tags': tags}))

    def pick_one(self) -> PickOneResult:
        """Pick one.
        """
        return self.call('pick_one', _args({}))
